-- New syllabus edition for this career.
insert into public.syllabus_editions (contest_name,role_name,contest_year)
select 'Polícia Federal','Escrivão de Polícia Federal',2021
where not exists (
  select 1 from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Escrivão de Polícia Federal' and contest_year=2021
);

-- Discipline breakdown derived directly from reading the prova's own item
-- text (command blocks and subject matter): Língua Portuguesa (1-18),
-- Redação Oficial (19-24), Direito Administrativo (25-27), Direito
-- Constitucional (28-30: competência constitucional da PF, crime
-- inafiançável do art. 5º CF, extradição), Direito Penal e Processual
-- Penal (31-33: cadeia de custódia, descaminho, flagrante preparado),
-- Legislação Penal Especial (34-36: Lei de Migração 13.445/2017, Lei de
-- Drogas 11.343/2006, Lei de Crimes Ambientais 9.605/1998), Estatística e
-- Probabilidade (37-48), Raciocínio Lógico-Matemático (49-60: análise
-- combinatória, lógica proposicional, conjuntos), Informática (61-96:
-- Internet, redes, segurança, cloud computing, sistemas de informação,
-- banco de dados, programação), Contabilidade (97-114), Arquivologia
-- (115-120). This differs from the Delegado breakdown (which had no
-- Estatística, Raciocínio Lógico, Informática, Contabilidade or
-- Arquivologia blocks and instead had much more Direito material),
-- reflecting Escrivão's own distinct edital objects of assessment.
with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Escrivão de Polícia Federal' and contest_year=2021
)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text,content_status)
select edition.id,'Prova objetiva',d.discipline,1,d.topic_text,'current'
from edition cross join (values
  ('Língua Portuguesa','Compreensão e interpretação de textos; tipologia textual; aspectos linguísticos: coesão e coerência, morfossintaxe, reescrita de frases e pontuação.'),
  ('Redação Oficial','Manual de Redação da Presidência da República: e-mail como documento oficial, exposição de motivos, pronomes de tratamento, grafia de datas, vocativos e padrão ofício.'),
  ('Direito Administrativo','Regime disciplinar do servidor público, poder de polícia administrativo e controle da administração pública.'),
  ('Direito Constitucional','Competência constitucional da Polícia Federal (art. 144 da CF), crimes inafiançáveis e extradição de brasileiro naturalizado (art. 5º da CF).'),
  ('Direito Penal e Processual Penal','Cadeia de custódia da prova, consumação do crime de descaminho e flagrante preparado.'),
  ('Legislação Penal Especial','Lei nº 13.445/2017 (Lei de Migração), Lei nº 11.343/2006 (Lei de Drogas) e Lei nº 9.605/1998 (crimes ambientais).'),
  ('Estatística e Probabilidade','Variáveis aleatórias contínuas, distribuições conjuntas, estimação de parâmetros e regressão linear simples.'),
  ('Raciocínio Lógico-Matemático','Análise combinatória, lógica proposicional (equivalência, negação, tabela-verdade, validade de argumentos) e teoria dos conjuntos.'),
  ('Informática','Internet e intranet, redes de computadores, segurança da informação, computação em nuvem, teoria geral de sistemas, banco de dados e programação (Python e R).'),
  ('Contabilidade','Fatos contábeis, escrituração, NBC TSP Estrutura Conceitual, avaliação de recebíveis e pronunciamentos técnicos do CPC.'),
  ('Arquivologia','Princípios arquivísticos, NOBRADE, gestão de documentos, classificação e tabela de temporalidade.')
) d(discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text;

